        if x in ('+', '-', '*', '/'):
            b = st.pop()
            a = st.pop()
            if x == '+':
                st.append(a + b)
            elif x == '-':
                st.append(a - b)
            elif x == '*':
                st.append(a * b)
            else:
                q = abs(a) // abs(b)
