    Considers parentheses (), square brackets [], and curly braces {}.
    All other characters are ignored.
    """
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set(matching.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
