def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    This implementation safely ignores any non‑numeric elements that may appear
    in the input (e.g., ``None`` or strings). Such elements are skipped because
    they cannot be compared with integers in a numeric subsequence.
    The algorithm uses patience sorting with binary search for O(n log n).
    """
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    # Filter to numeric values (ints). Floats are also accepted if they are
    # comparable to ints, but we cast them to int for consistency.
    filtered = []
    for x in nums:
        if isinstance(x, (int,)):
            filtered.append(x)
        else:
            # ignore non‑int values
            continue
    if not filtered:
        return 0
    import bisect
    tails = []
    for x in filtered:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

